/// is not a valid glob, then this returns the original string as the expansion result.
///
/// Note: This matches the default behavior of Bash, but is known to be
/// error-prone. We might want to change this behavior in the future.
struct ExternalGlob {
    strip_working_directory: bool,
    keep_unmatched_pattern: bool,
}

impl ExternalGlob {
    fn expand_glob(&self, glob: &GlobExpansion) -> Result<Vec<String>, ShellError> {
        let options = nu_glob::MatchOptions {
            case_sensitive: glob.case_sensitive,
            require_literal_separator: glob.require_literal_separator,
            require_literal_leading_dot: glob.require_literal_leading_dot,
            recursive_match_hidden_dir: true,
        };
        let pattern = glob.pattern.as_str();
        let cwd = glob.cwd.as_path();
        let Ok(paths) = nu_glob::glob_with_parent(pattern, options, cwd) else {
            return Ok(vec![pattern.into()]);
        };

        let mut result = vec![];
        for path in paths {
            let path = path.map_err(|err| ShellError::IOErrorSpanned {
                msg: format!("{}: {:?}", err.path().display(), err.error()),
                span: glob.span,
            })?;
            // Strip PWD from the resulting paths if possible.
            let path_stripped = if self.strip_working_directory {
                path.strip_prefix(cwd).unwrap_or(&path)
            } else {
                &path
            };
            let path_string = path_stripped.to_string_lossy().to_string();
            result.push(path_string);
        }

        if result.is_empty() && self.keep_unmatched_pattern {
            result.push(pattern.to_string());
        }

        Ok(result)
    }
}

